export const COSTS={floor:[2,0],terrace:[3,0],wall:[4,0],gate:[4,2],stairs:[3,1],tower:[12,7],roof:[1,3],garden:[0,3],house:[3,4],spawn:[2,1],core:[16,8],cannon:[7,6],heavyCannon:[12,5],trebuchet:[10,14],battlement:[4,0]};
export const KEY='crusaders-castle-trials:v1';
export class Round {
 constructor({mode='showcase',seconds=1200}={}){this.mode=mode;this.duration=seconds;this.remaining=seconds;this.phase='build';this.layout=[];this.stock=[40,25];this.history=[];this.time=0;this.revision=0;}
 tick(dt){if(this.phase!=='build')return;dt=Math.max(0,dt);this.time+=dt;this.remaining=Math.max(0,this.remaining-dt);}
 place(piece){if(this.phase!=='build')throw Error('Round finished. Retry to edit.');if(!Object.hasOwn(COSTS,piece.type)||!Number.isInteger(piece.x)||!Number.isInteger(piece.z)||!Number.isInteger(piece.layer)||piece.x<0||piece.x>11||piece.z<0||piece.z>11||piece.layer<0||piece.layer>2)throw Error('Choose a legal plot tile and one of three layers.');if(piece.type==='core'&&this.layout.some(p=>p.type==='core'&&(p.x!==piece.x||p.z!==piece.z||p.layer!==piece.layer)))throw Error('Only one main core.');const at=this.layout.findIndex(p=>p.x===piece.x&&p.z===piece.z&&p.layer===piece.layer),old=at<0?null:this.layout[at],cost=COSTS[piece.type],refund=old?COSTS[old.type]:[0,0];if(cost.some((v,i)=>v>this.stock[i]+refund[i]))throw Error('Gather more resources for this piece.');this.stock=this.stock.map((v,i)=>v+refund[i]-cost[i]);if(at>=0)this.layout.splice(at,1);this.layout.push({...piece});this.history.push({old,next:{...piece}});this.revision++;}
 erase(cell){if(this.phase!=='build')return false;const at=this.layout.findIndex(p=>p.x===cell.x&&p.z===cell.z&&p.layer===cell.layer);if(at<0)return false;const old=this.layout.splice(at,1)[0];this.stock=this.stock.map((v,i)=>v+COSTS[old.type][i]);this.history.push({old,next:null});this.revision++;return true;}
 undo(){if(this.phase!=='build')return false;const h=this.history.at(-1);if(!h)return false;const credit=h.next?COSTS[h.next.type]:[0,0],debit=h.old?COSTS[h.old.type]:[0,0];if(debit.some((v,i)=>v>this.stock[i]+credit[i]))return false;this.history.pop();this.stock=this.stock.map((v,i)=>v+credit[i]-debit[i]);const cell=h.next||h.old;this.layout=this.layout.filter(p=>p.x!==cell.x||p.z!==cell.z||p.layer!==cell.layer);if(h.old)this.layout.push(h.old);this.revision++;return true;}
 retry(){this.remaining=this.duration;this.phase='build';this.history=[];this.revision++;}
 finish(valid){if(this.phase!=='build')return;this.phase=valid?(this.mode==='showcase'?'showcase':'trial'):'failed';}
}
